def ensure_runtime_assets():
    for d in [Config.UPLOAD_FOLDER, Config.RESULTS_FOLDER, Config.SHOWCASE_FOLDER,
              Config.DATASET_DIR, os.path.dirname(Config.MODEL_WEIGHTS_PATH)]:
        os.makedirs(d, exist_ok=True)
    for fname, b64_str in EMBEDDED_SHOWCASE.items():
        fpath = os.path.join(Config.SHOWCASE_FOLDER, fname)
        if not os.path.exists(fpath):
            with open(fpath, "wb") as f:
                f.write(base64.b64decode(b64_str))


class ImageProcessingPipeline:
    def __init__(self):
        self.face_cascade = None
        if hasattr(cv2, 'CascadeClassifier'):
            try:
                cascade_path = cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'
                if os.path.exists(cascade_path):
                    self.face_cascade = cv2.CascadeClassifier(cascade_path)
            except Exception:
                pass

    def measure_sharpness(self, gray_img):
        try:
            return float(cv2.Laplacian(gray_img, cv2.CV_64F).var())
        except Exception:
            return 100.0

    def process_image(self, input_image_path, output_annotated_name, output_crop_name):
        if not os.path.exists(input_image_path):
            return {"success": False, "error": "Image file not found on server."}
        img = cv2.imread(input_image_path)
        if img is None:
            return {"success": False, "error": "Failed to decode image. Ensure format is JPG, PNG, or WEBP."}
        h, w = img.shape[:2]
        if h < Config.MIN_IMAGE_RESOLUTION[1] or w < Config.MIN_IMAGE_RESOLUTION[0]:
            return {"success": False, "error": f"Image resolution too low ({w}x{h}px). Minimum required is 64x64px."}

        gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
        sharpness_score = round(self.measure_sharpness(gray), 1)
        is_blurry = sharpness_score < Config.SOFT_BLUR_THRESHOLD

        faces = []
        if self.face_cascade is not None and not self.face_cascade.empty():
            try:
                faces = self.face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=4, minSize=(50, 50))
            except Exception:
                faces = []

        annotated_img = img.copy()
        if len(faces) > 0:
            inspection_mode = "Facial Portrait Scan"
            x, y, fw, fh = max(faces, key=lambda rect: rect[2] * rect[3])
            pad_x, pad_y = int(0.15 * fw), int(0.15 * fh)
            roi_crop = img[max(0, y - pad_y):min(h, y + fh + pad_y), max(0, x - pad_x):min(w, x + fw + pad_x)]
            cv2.rectangle(annotated_img, (x, y), (x + fw, y + fh), (0, 168, 150), 3)
            cv2.putText(annotated_img, f"Face ROI: {fw}x{fh}px", (x, max(25, y - 10)),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.6, (0, 168, 150), 2, cv2.LINE_AA)
        else:
            inspection_mode = "Direct Cutaneous Lesion Scan"
            cx, cy = w // 2, h // 2
            fw, fh = int(w * 0.75), int(h * 0.75)
            x, y = max(0, cx - fw // 2), max(0, cy - fh // 2)
            roi_crop = img[y:y+fh, x:x+fw]
            radius = int(min(fw, fh) * 0.45)
            cv2.circle(annotated_img, (cx, cy), radius, (0, 168, 150), 2)
            cv2.circle(annotated_img, (cx, cy), radius + 8, (216, 180, 0), 1)
            cv2.line(annotated_img, (cx - radius - 15, cy), (cx + radius + 15, cy), (0, 168, 150), 1)
            cv2.line(annotated_img, (cx, cy - radius - 15), (cx, cy + radius + 15), (0, 168, 150), 1)
            cv2.putText(annotated_img, "Dermoscopic Lesion ROI", (max(15, x), max(25, y - 10)),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.6, (0, 168, 150), 2, cv2.LINE_AA)

        os.makedirs(Config.RESULTS_FOLDER, exist_ok=True)
        cv2.imwrite(os.path.join(Config.RESULTS_FOLDER, output_annotated_name), annotated_img)
        cv2.imwrite(os.path.join(Config.RESULTS_FOLDER, output_crop_name), roi_crop)

        rgb_roi = cv2.cvtColor(roi_crop, cv2.COLOR_BGR2RGB)
        resized_roi = cv2.resize(rgb_roi, Config.IMAGE_SIZE)

        return {
            "success": True,
            "inspection_mode": inspection_mode,
            "sharpness_score": sharpness_score,
            "blur_warning": is_blurry,
            "faces_detected": len(faces),
            "roi_box": {"x": int(x), "y": int(y), "w": int(fw), "h": int(fh)},
            "annotated_filename": output_annotated_name,
            "crop_filename": output_crop_name,
            "preprocessed_tensor_input": resized_roi
        }


class FacialHealthClassifier(nn.Module if TORCH_AVAILABLE else object):
    def __init__(self, num_classes=7, pretrained=False):
        if not TORCH_AVAILABLE:
            return
        super().__init__()
        weights = models.MobileNet_V2_Weights.DEFAULT if pretrained else None
        try:
            self.backbone = models.mobilenet_v2(weights=weights)
        except Exception:
            self.backbone = models.mobilenet_v2(pretrained=False)
        in_features = self.backbone.classifier[1].in_features
        self.backbone.classifier = nn.Sequential(
            nn.Dropout(p=0.3), nn.Linear(in_features, 256), nn.ReLU(inplace=True),
            nn.BatchNorm1d(256), nn.Dropout(p=0.4), nn.Linear(256, num_classes)
        )

    def forward(self, x):
        return self.backbone(x)


class ModelEngine:
    def __init__(self):
        self.device = torch.device("cuda" if torch.cuda.is_available() else "cpu") if TORCH_AVAILABLE else "cpu"
        self.classes = Config.HAM10000_CLASSES
        self.num_classes = len(self.classes)
        self.has_trained_weights = False
        self.model = None
        if TORCH_AVAILABLE and os.path.exists(Config.MODEL_WEIGHTS_PATH):
            try:
                self.model = FacialHealthClassifier(num_classes=self.num_classes, pretrained=False)
                self.model.to(self.device)
                self.model.load_state_dict(torch.load(Config.MODEL_WEIGHTS_PATH, map_location=self.device))
                self.model.eval()
                self.has_trained_weights = True
            except Exception:
                self.has_trained_weights = False

    def predict(self, face_rgb_numpy):
        if TORCH_AVAILABLE and self.has_trained_weights and self.model is not None:
            transform = transforms.Compose([
                transforms.ToTensor(),
                transforms.Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225])
            ])
            input_tensor = transform(face_rgb_numpy).unsqueeze(0).to(self.device)
            with torch.no_grad():
                probabilities = torch.softmax(self.model(input_tensor), dim=1).cpu().numpy()[0]
            top_index = int(np.argmax(probabilities))
            return {
                "predicted_class": self.classes[top_index],
                "confidence_score": round(float(probabilities[top_index]) * 100, 2),
                "distribution": {c: round(float(p) * 100, 2) for c, p in zip(self.classes, probabilities)}
            }

        face_224 = cv2.resize(face_rgb_numpy, (224, 224))
        h, w = 224, 224
        center_roi = face_224[int(h*0.25):int(h*0.75), int(w*0.25):int(w*0.75)]
        r, g, b = center_roi[:, :, 0].astype(float), center_roi[:, :, 1].astype(float), center_roi[:, :, 2].astype(float)
        lab = cv2.cvtColor(center_roi.astype(np.uint8), cv2.COLOR_RGB2LAB)
        red_dominance = np.mean(r) / (np.mean(g) + np.mean(b) + 1e-5)
        l_std, l_mean = np.std(lab[:, :, 0]), np.mean(lab[:, :, 0])
        rg_diff = np.clip(r - g, 0, 255).astype(np.uint8)
        texture_roughness = cv2.Laplacian(rg_diff, cv2.CV_64F).var()
        half_w = center_roi.shape[1] // 2
        asymmetry_score = float(np.mean(np.abs(center_roi[:, :half_w].astype(float) - np.fliplr(center_roi[:, half_w:]).astype(float))))

        logits = np.array([2.8, 1.2, 0.8, 0.6, 0.5, 0.5, 0.4], dtype=float)
        if red_dominance > 0.62:
            logits[3] += (red_dominance - 0.58) * 80.0 + 3.0; logits[0] -= 1.5
        if texture_roughness > 350.0:
            logits[4] += min(8.0, (texture_roughness - 300.0) / 200.0 + 3.5); logits[0] -= 1.8
        if l_std > 18.0 and red_dominance > 0.58:
            logits[5] += (l_std - 15.0) * 0.4 + (red_dominance - 0.55) * 20.0 + 2.0; logits[0] -= 1.8
        if asymmetry_score > 32.0 and l_std > 16.0:
            logits[6] += (asymmetry_score - 28.0) * 0.35 + (l_std - 14.0) * 0.4 + 3.0; logits[0] -= 2.0
        if l_std > 13.0 and asymmetry_score <= 30.0 and red_dominance <= 0.60:
            logits[1] += (l_std - 11.0) * 0.8 + 2.5; logits[0] -= 1.0
        if l_mean < 185.0 and l_std < 14.0:
            logits[2] += 2.8; logits[0] -= 0.8
        if texture_roughness < 150.0 and l_std < 12.0 and red_dominance < 0.60:
            logits[0] += 3.0

        exp_l = np.exp(logits - np.max(logits))
        probs = exp_l / np.sum(exp_l)
        top_idx = int(np.argmax(probs))
        return {
            "predicted_class": self.classes[top_idx],
            "confidence_score": round(float(probs[top_idx]) * 100, 2),
            "distribution": {c: round(float(p) * 100, 2) for c, p in zip(self.classes, probs)},
            "asymmetry_metric": round(asymmetry_score, 1),
            "texture_roughness": round(texture_roughness, 1)
        }


