image_pipeline = ImageProcessingPipeline()
model_engine = ModelEngine()


def is_allowed_extension(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in Config.ALLOWED_EXTENSIONS


def _active_model_label():
    return "MobileNetV2 (HAM10000 PyTorch)" if model_engine.has_trained_weights else "ABCD Feature Softmax Engine (MobileNetV2 Fallback)"


def _run_full_screening(input_path, input_filename, unique_id):
    annotated_filename = f"annotated_{unique_id}.jpg"
    crop_filename = f"crop_{unique_id}.jpg"
    lime_filename = f"lime_{unique_id}.jpg"

    t0 = time.perf_counter()
    cv_result = image_pipeline.process_image(input_path, annotated_filename, crop_filename)
    if not cv_result["success"]:
        return {"success": False, "error": cv_result["error"]}

    inference = model_engine.predict(cv_result["preprocessed_tensor_input"])
    inference_time_ms = round((time.perf_counter() - t0) * 1000.0, 2)
    assessment = RiskAssessmentEngine.evaluate(inference["predicted_class"], inference["confidence_score"])
    lime_result = generate_lime_explanation(cv_result["preprocessed_tensor_input"], model_engine, inference["predicted_class"], lime_filename)
    model_used = _active_model_label()
    screening_id = f"SCR-{unique_id.upper()}"

    entry = record_screening({
        "screening_id": screening_id,
        "inspection_mode": cv_result["inspection_mode"],
        "predicted_class": inference["predicted_class"],
        "risk_tier": assessment["risk_tier"],
        "tier_badge": assessment["tier_badge"],
        "model_used": model_used,
        "confidence_score": inference["confidence_score"],
        "vital_score": assessment["vital_score"],
        "inference_time_ms": inference_time_ms,
        "sharpness_score": cv_result["sharpness_score"],
        "blur_warning": cv_result["blur_warning"]
    })

    return {
        "success": True,
        "screening_id": screening_id,
        "timestamp": entry["timestamp"],
        "model_used": model_used,
        "inference_time_ms": inference_time_ms,
        "cv_result": {
            "inspection_mode": cv_result["inspection_mode"],
            "sharpness_score": cv_result["sharpness_score"],
            "blur_warning": cv_result["blur_warning"],
            "blur_threshold": Config.SOFT_BLUR_THRESHOLD
        },
        "inference": inference,
        "assessment": assessment,
        "lime": lime_result,
        "images": {
            "original": url_for('static', filename=f'uploads/{input_filename}'),
            "annotated": url_for('static', filename=f'results/{annotated_filename}'),
            "crop": url_for('static', filename=f'results/{crop_filename}'),
            "lime": url_for('static', filename=f'results/{lime_filename}')
        }
    }


