@app.route('/api/analyze', methods=['POST'])
@app.route('/api/predict', methods=['POST'])
def api_analyze():
    try:
        camera_data = request.form.get('camera_image')
        uploaded_file = request.files.get('file')
        unique_id = str(uuid.uuid4())[:8]
        input_filename = f"scan_{unique_id}.jpg"
        input_path = os.path.join(Config.UPLOAD_FOLDER, input_filename)

        if camera_data and camera_data.startswith('data:image'):
            _, encoded = camera_data.split(',', 1)
            with open(input_path, 'wb') as f:
                f.write(base64.b64decode(encoded))
        elif uploaded_file and uploaded_file.filename != '':
            if not is_allowed_extension(uploaded_file.filename):
                return jsonify({"success": False, "error": "Unsupported file format."}), 400
            ext = uploaded_file.filename.rsplit('.', 1)[1].lower()
            input_filename = f"scan_{unique_id}.{ext}"
            input_path = os.path.join(Config.UPLOAD_FOLDER, input_filename)
            uploaded_file.save(input_path)
        else:
            return jsonify({"success": False, "error": "No image provided."}), 400

        res = _run_full_screening(input_path, input_filename, unique_id)
        if not res["success"]:
            return jsonify(res), 422
        return jsonify(res)
    except Exception as e:
        traceback.print_exc()
        return jsonify({"success": False, "error": str(e)}), 500


_camera_cap = None
_last_camera_frame = None


def _get_camera():
    global _camera_cap
    if _camera_cap is None or not _camera_cap.isOpened():
        _camera_cap = cv2.VideoCapture(0)
    return _camera_cap


def _release_camera():
    global _camera_cap
    if _camera_cap is not None:
        try:
            _camera_cap.release()
        except Exception:
            pass
        _camera_cap = None


@app.route('/api/camera/status')
def api_camera_status():
    cap = _get_camera()
    ok = bool(cap is not None and cap.isOpened())
    if not ok:
        _release_camera()
    return jsonify({"available": ok})


@app.route('/api/camera/feed')
def api_camera_feed():
    def gen():
        global _last_camera_frame
        cap = _get_camera()
        while cap is not None and cap.isOpened():
            ret, frame = cap.read()
            if not ret:
                break
            _last_camera_frame = frame
            ok, buf = cv2.imencode('.jpg', frame, [cv2.IMWRITE_JPEG_QUALITY, 85])
            if not ok:
                continue
            yield (b'--frame\r\nContent-Type: image/jpeg\r\n\r\n' + buf.tobytes() + b'\r\n')
    return Response(gen(), mimetype='multipart/x-mixed-replace; boundary=frame')


@app.route('/api/camera/capture', methods=['POST'])
def api_camera_capture():
    global _last_camera_frame
    frame = _last_camera_frame
    if frame is None:
        cap = _get_camera()
        if cap is not None and cap.isOpened():
            ret, f = cap.read()
            if ret:
                frame = f
    if frame is None:
        return jsonify({"success": False, "error": "No camera frame available."}), 422
    h, w = frame.shape[:2]
    ok, buf = cv2.imencode('.jpg', frame, [cv2.IMWRITE_JPEG_QUALITY, 92])
    if not ok:
        return jsonify({"success": False, "error": "Failed to encode camera frame."}), 500
    b64 = base64.b64encode(buf.tobytes()).decode('utf-8')
    return jsonify({"success": True, "image_data": f"data:image/jpeg;base64,{b64}", "width": w, "height": h})


@app.route('/api/camera/stop', methods=['POST'])
def api_camera_stop():
    _release_camera()
    return jsonify({"success": True})


